-- SafeVision — демонстрационные данные (даты рассчитываются относительно текущего момента)
BEGIN;



UPDATE facilities SET responsible_id = v.emp FROM (VALUES (1, 4), (2, 5), (3, 6), (4, 7), (5, 8)) AS v(fac, emp) WHERE facilities.id = v.fac;








-- Автоматические проверки СИЗ по камерам: число проверок с нарушениями за день равно числу нарушений за этот день
SELECT c.facility_id, c.id,
       (SELECT e.id FROM employees e WHERE e.facility_id = c.facility_id ORDER BY ((e.id * 31 + g.i * 17 + d.d) % 97) LIMIT 1),
       'ai', NOT (g.i <= v.cnt), TRUE, TRUE, g.i <= v.cnt,
       CASE WHEN d.d = 0 THEN GREATEST(date_trunc('day', now()) + interval '1 minute', now() - make_interval(mins => g.i * 3))
            ELSE date_trunc('day', now()) - make_interval(days => d.d) + make_interval(hours => 7 + (g.i * 5) % 12, mins => (g.i * 13) % 60) END
FROM generate_series(0, 44) AS d(d)
CROSS JOIN LATERAL (SELECT count(*)::int AS cnt FROM violations
                    WHERE detected_at >= date_trunc('day', now()) - make_interval(days => d.d)
                      AND detected_at <  date_trunc('day', now()) - make_interval(days => d.d - 1)) AS v
CROSS JOIN LATERAL generate_series(1, CASE WHEN d.d = 0 THEN 100 ELSE 105 + (d.d * 37) % 40 END) AS g(i)
CROSS JOIN LATERAL (SELECT id, facility_id FROM cameras WHERE status = 'online' ORDER BY ((id * 7 + g.i) % 12) LIMIT 1) AS c;

SELECT 1, 1, 3, 'ai', TRUE, TRUE, NOT (d.d = 9), d.d = 9,
       date_trunc('day', now()) - make_interval(days => d.d) + interval '8 hours 40 minutes'
FROM generate_series(1, 30) AS d(d)
WHERE extract(isodow FROM now() - make_interval(days => d.d)) < 6;

SELECT 1 + (d.d % 5), (SELECT id FROM employees WHERE facility_id = 1 + (d.d % 5) ORDER BY id OFFSET (d.d % 4) LIMIT 1),
       2, 'inspector', TRUE, d.d % 6 <> 0, TRUE, d.d % 6 = 0,
       date_trunc('day', now()) - make_interval(days => d.d) + interval '14 hours'
FROM generate_series(1, 30) AS d(d);



1. Перед работой осмотрите каску: на корпусе не должно быть трещин, вмятин и следов оплавления.
2. Отрегулируйте оголовье по размеру головы — каска не должна смещаться при наклоне.
3. Используйте подбородочный ремень при работе на высоте и в ветреную погоду.
4. Не храните в каске посторонние предметы и не наносите на неё краску и растворители.
5. Каска подлежит замене после сильного удара или по истечении срока службы, указанного изготовителем.', now() - interval '1 days'),
  ('Работа на высоте', 'Требования безопасности при работе на высоте: страховочные системы, ограждения, допуск.', 'video', 'Высота', 220, NULL, 16, 'Работой на высоте считаются работы, при которых существует риск падения с высоты 1,8 м и более.
1. К работе допускаются лица, прошедшие обучение, стажировку и имеющие группу по безопасности работ на высоте.
2. Перед началом работ проверьте страховочную привязь, стропы и анкерные устройства.
3. Закрепляйтесь к надёжной точке анкерного крепления выше уровня рабочего места.
4. Инструмент и материалы поднимайте в сумках, не допускайте их падения.
5. Запрещено работать на высоте при ветре более 15 м/с, гололёде и грозе.', now() - interval '7 days'),
  ('Пожарная безопасность', 'Действия при возгорании, использование огнетушителей, эвакуация.', 'video', 'Пожарная', 260, NULL, 17, 'При обнаружении возгорания:
1. Немедленно сообщите по телефону 101 (112) и руководителю.
2. Оповестите людей и при возможности отключите электрооборудование.
3. Используйте первичные средства пожаротушения: выдерните чеку огнетушителя, направьте раструб на очаг и нажмите рычаг.
4. При сильном задымлении покиньте помещение по путям эвакуации, пригнувшись.
5. Не используйте лифты и не возвращайтесь в горящее помещение.', now() - interval '13 days'),
  ('Электробезопасность', 'Основные правила безопасной работы с электроустановками и электроинструментом.', 'video', 'Электро', 190, NULL, 18, '1. Перед работой проверьте исправность электроинструмента, изоляцию кабеля и вилки.
2. Не открывайте электрощиты и не снимайте защитные кожухи — это работа электротехнического персонала.
3. Не прикасайтесь к оборванным проводам и не наступайте на них.
4. При поражении человека током — обесточьте установку, не касаясь пострадавшего голыми руками.
5. Вызовите медицинскую помощь и приступите к оказанию первой помощи.', now() - interval '19 days'),
  ('Первая помощь на производстве', 'Порядок оказания первой помощи при травмах до прибытия медиков.', 'video', 'Медицина', 300, NULL, 19, '1. Убедитесь в отсутствии опасности для себя и пострадавшего.
2. Вызовите скорую помощь (103 или 112).
3. Остановите наружное кровотечение давящей повязкой или жгутом.
4. При отсутствии дыхания приступите к сердечно-лёгочной реанимации.
5. Не оставляйте пострадавшего одного до прибытия медиков.', now() - interval '25 days'),
  ('Правила применения СИЗ', 'Перечень средств индивидуальной защиты по профессиям и порядок их выдачи.', 'document', 'СИЗ', NULL, 1240, 20, 'Документ устанавливает нормы выдачи и порядок применения средств индивидуальной защиты на предприятии.
Обязательные СИЗ в производственных цехах: защитная каска, сигнальный жилет, защитная обувь, перчатки.
На участках механической обработки и сварки дополнительно обязательны защитные очки или щитки.
СИЗ выдаются бесплатно на посту выдачи СИЗ под роспись в личной карточке учёта.', now() - interval '31 days'),
  ('Инструкция по охране труда для слесаря-ремонтника', 'ИОТ-07: требования безопасности до начала, во время и по окончании работы.', 'document', 'Инструкции', NULL, 860, 21, '1. Общие требования: к работе допускаются лица не моложе 18 лет, прошедшие медосмотр и инструктажи.
2. До начала работы: надеть спецодежду и СИЗ, проверить исправность инструмента.
3. Во время работы: ремонт оборудования выполнять только после отключения и вывешивания плаката «Не включать!».
4. По окончании работы: убрать инструмент, сообщить мастеру о выявленных неисправностях.', now() - interval '37 days'),
  ('Порядок действий при пожаре', 'План эвакуации и обязанности работников при пожаре.', 'document', 'Пожарная', NULL, 540, 22, 'Каждый работник обязан знать расположение путей эвакуации, огнетушителей и пожарных кранов на своём участке.
При сигнале пожарной тревоги прекратите работу, отключите оборудование и выйдите к месту сбора у КПП №1.
Руководители подразделений проверяют наличие людей по спискам и докладывают в штаб пожаротушения.', now() - interval '43 days');

COMMIT;
