INSERT INTO training_materials (title, description, kind, topic, duration_sec, file_size_kb, image_id, content, created_at) VALUES
  ('Использование каски', 'Как правильно подобрать, надеть и отрегулировать защитную каску, сроки службы и уход.', 'video', 'СИЗ', 135, NULL, 15, 'Защитная каска защищает голову от падающих предметов, ударов о конструкции и поражения электрическим током.
